input.content:
// Decides whether the assistant may send one WhatsApp message through the
// WhatsApp Business Platform (Cloud API). Pure function, no I/O, no sends.
//
// Rules, checked in this order:
// 1. The patient must have opted in to WhatsApp messages from us. Applies to
//    every message type.
// 2. A "template" message (pre-approved Meta template) may be sent at any
//    time after opt-in, so it is allowed.
// 3. A "text" (free-form) message is allowed only inside the 24-hour customer
//    service window, which opens with the patient's most recent inbound message.
//
// Meta's webhook `timestamp` is Unix time in whole seconds, delivered as a
// string. It is converted to milliseconds before any date arithmetic.

const SERVICE_WINDOW_MS = 24 * 60 * 60 * 1000;

function deny(reason) {
  return { allowed: false, reason };
}

export function decideWhatsApp(message, now) {
  const nowMs = now.getTime();
  if (!Number.isFinite(nowMs)) {
    throw new TypeError('now must be a valid Date');
  }

  const type = message?.type;
  const contact = message?.contact;

  if (contact?.optedIn !== true) {
    return deny('not_opted_in');
  }

  if (type === 'template') {
    return { allowed: true, reason: null };
  }

  if (type !== 'text') {
    return deny('unsupported_message_type');
  }

  const inbound = contact.lastInboundTimestamp;
  if (inbound === null || inbound === undefined) {
    return deny('no_inbound_message');
  }
  if (typeof inbound !== 'string' || !/^\d+$/.test(inbound)) {
    return deny('invalid_inbound_timestamp');
  }

  const inboundMs = Number(inbound) * 1000;
  if (!Number.isFinite(inboundMs)) {
    return deny('invalid_inbound_timestamp');
  }

  const elapsedMs = nowMs - inboundMs;
  if (elapsedMs < 0) {
    return deny('inbound_timestamp_in_future');
  }
  if (elapsedMs >= SERVICE_WINDOW_MS) {
    return deny('service_window_closed');
  }

  return { allowed: true, reason: null };
}

input.command:
node --version && node --input-type=module -e '
import assert from "node:assert/strict";
import { decideWhatsApp as d } from "./bot.mjs";
const TS = "1767272400";
const T0 = Number(TS) * 1000;
const at = (ms) => new Date(T0 + ms);
const H = 3600e3;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: TS, ...over });
const ok = { allowed: true, reason: null };
const no = (r) => ({ allowed: false, reason: r });

// template: allowed regardless of window
assert.deepEqual(d({ type: "template", contact: c() }, at(1000 * H)), ok);
assert.deepEqual(d({ type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0)), ok);
// opt-in gate applies to all types
assert.deepEqual(d({ type: "template", contact: c({ optedIn: false }) }, at(0)), no("not_opted_in"));
assert.deepEqual(d({ type: "text", contact: c({ optedIn: false }) }, at(0)), no("not_opted_in"));
assert.deepEqual(d({ type: "text", contact: c({ optedIn: "true" }) }, at(0)), no("not_opted_in"));
assert.deepEqual(d({ type: "text", contact: {} }, at(0)), no("not_opted_in"));
assert.deepEqual(d({ type: "text" }, at(0)), no("not_opted_in"));
// text inside window
assert.deepEqual(d({ type: "text", contact: c() }, at(0)), ok);
assert.deepEqual(d({ type: "text", contact: c() }, at(24 * H - 1)), ok);
// text at / after 24h
assert.deepEqual(d({ type: "text", contact: c() }, at(24 * H)), no("service_window_closed"));
assert.deepEqual(d({ type: "text", contact: c() }, at(48 * H)), no("service_window_closed"));
// never messaged
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0)), no("no_inbound_message"));
// bad timestamps
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: "abc" }) }, at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d({ type: "text", contact: c({ lastInboundTimestamp: "" }) }, at(0)), no("invalid_inbound_timestamp"));
// future timestamp
assert.deepEqual(d({ type: "text", contact: c() }, at(-1)), no("inbound_timestamp_in_future"));
// unknown type
assert.deepEqual(d({ type: "image", contact: c() }, at(0)), no("unsupported_message_type"));
// bad clock
assert.throws(() => d({ type: "text", contact: c() }, new Date("x")), TypeError);
console.log("all assertions passed");
'
